def brute_force(k: int, w: int, profits: List[int], capital: List[int]) -> int:
    # k rounds; each round rescans all projects for the best affordable unpicked one.
    done = [False] * len(profits)
    for _ in range(k):
        best = -1
        for j in range(len(profits)):
            if not done[j] and capital[j] <= w and (best < 0 or profits[j] > profits[best]):
                best = j
        if best < 0:
            break
        done[best] = True
        w += profits[best]
    return w

def brute_force(courses: List[List[int]]) -> int:
    # Exponential: try every subset in deadline order and keep the largest feasible one.
    cs = sorted(courses, key=lambda c: c[1])
    n, best = len(cs), 0
    for mask in range(1 << n):
        time, ok, count = 0, True, 0
        for i in range(n):
            if mask >> i & 1:
                time += cs[i][0]
                count += 1
                if time > cs[i][1]:
                    ok = False
                    break
        if ok:
            best = max(best, count)
    return best

