def brute_force(nums: List[int]) -> int:
    # Exponential: every element independently picks one rung of its ladder
    # (odd x -> {x, 2x}; even x -> {x, x/2, ..., odd core}); score max - min.
    from itertools import product
    ladders = []
    for x in nums:
        if x % 2:
            rungs = [x, 2 * x]
        else:
            rungs = []
            while x % 2 == 0:
                rungs.append(x)
                x //= 2
            rungs.append(x)                                 # the odd core
        ladders.append(rungs)
    return min(max(choice) - min(choice) for choice in product(*ladders))

def brute_force(target: int, startFuel: int, stations: List[List[int]]) -> int:
    # Exponential: every subset of stations, simulated in order; keep the smallest feasible one.
    n, best = len(stations), -1
    for mask in range(1 << n):
        fuel, ok = startFuel, True
        for i in range(n):
            if mask >> i & 1:
                if fuel < stations[i][0]:
                    ok = False
                    break
                fuel += stations[i][1]
        if ok and fuel >= target:
            count = bin(mask).count("1")
            if best < 0 or count < best:
                best = count
    return best

def brute_force(n: int, meetings: List[List[int]]) -> int:
    # Scan all n rooms for every meeting: lowest free room, else earliest-free room.
    meetings = sorted(meetings)
    free_at = [0] * n
    count = [0] * n
    for start, end in meetings:
        room = next((r for r in range(n) if free_at[r] <= start), -1)
        if room < 0:
            room = min(range(n), key=lambda r: (free_at[r], r))
            end = free_at[room] + (end - start)
        free_at[room] = end
        count[room] += 1
    return count.index(max(count))

def brute_force(s: str, k: int) -> str:
    # Exponential backtracking: at each slot try every char not used in the previous k-1 slots.
    counts = Counter(s)
    out: List[str] = []

    def place() -> bool:
        if len(out) == len(s):
            return True
        recent = set(out[-(k - 1):]) if k > 1 else set()
        for ch in sorted(counts):
            if counts[ch] and ch not in recent:
                counts[ch] -= 1
                out.append(ch)
                if place():
                    return True
                out.pop()
                counts[ch] += 1
        return False

    return "".join(out) if place() else ""

