def brute_force(buildings: List[List[int]]) -> List[List[int]]:
    # At every edge x, rescan all buildings for the tallest covering x (left <= x < right).
    xs = sorted({x for l, r, _ in buildings for x in (l, r)})
    out, prev = [], 0
    for x in xs:
        h = max((hh for l, r, hh in buildings if l <= x < r), default=0)
        if h != prev:
            out.append([x, h])
            prev = h
    return out

def brute_force(schedule: List[List[Interval]]) -> List[Interval]:
    # Every (end, start) pair is a candidate gap; keep it if no interval covers its interior.
    all_iv = [iv for emp in schedule for iv in emp]
    gaps = set()
    for a in all_iv:
        for b in all_iv:
            if a.end < b.start and all(iv.end <= a.end or iv.start >= b.start for iv in all_iv):
                gaps.add((a.end, b.start))
    return [Interval(s, e) for s, e in sorted(gaps)]

